import { describe, it, expect, vi, beforeEach } from 'vitest'
import { mintPrimitiveProxyToken } from '@/lib/build/primitive-proxy-token'

/**
 * #443 — exercises the ACTUAL injected fetch-shim script (as generated by
 * dbTokenShim in app/api/preview/[id]/route.ts) in a simulated browser
 * fetch(), rather than just asserting on the generated string. Proves the
 * shim really attaches the right primitive-proxy token header on a
 * /api/primitive/{name}/... call, and leaves other requests untouched —
 * this is the part a generated app actually depends on at runtime.
 *
 * The shim string is reproduced here (not imported — it is a private,
 * unexported function in the route file, matching this codebase's existing
 * convention for that file's original #331 shim). If the route's shim logic
 * changes, this test defines the required runtime behavior.
 */
function dbTokenShim(token: string, primitiveTokens: Record<string, string> = {}): string {
  if (!token && Object.keys(primitiveTokens).length === 0) return ''
  return `(function(){
  var T=${JSON.stringify(token)};var PT=${JSON.stringify(primitiveTokens)};var of=window.fetch;
  window.fetch=function(input,init){
    try{
      var u=typeof input==='string'?input:((input&&input.url)||'');
      if(T&&u.indexOf('/api/db')===0){
        init=init||{};
        var h=new Headers(init.headers||((typeof input==='object'&&input.headers)||undefined));
        h.set('x-ainative-db-token',T);
        init.headers=h;
      } else if(u.indexOf('/api/primitive/')===0){
        var m=u.match(/^\\/api\\/primitive\\/([a-z]+)\\//);
        var pt=m&&PT[m[1]];
        if(pt){
          init=init||{};
          var h2=new Headers(init.headers||((typeof input==='object'&&input.headers)||undefined));
          h2.set('x-ainative-primitive-token',pt);
          init.headers=h2;
        }
      }
    }catch(e){}
    return of.call(this,input,init);
  };
})();`
}

function runShimAgainst(shimSrc: string, requestUrl: string): { url: string; init: any } {
  let captured: { url: string; init: any } | null = null
  const of = vi.fn(async (input: any, init: any) => {
    captured = { url: input, init }
    return new Response('{}')
  })
  const win: any = { fetch: of }
  // eslint-disable-next-line no-new-func
  new Function('window', shimSrc)(win)
  return new Promise((resolve) => {
    win.fetch(requestUrl).then(() => resolve(captured!))
  }) as any
}

describe('the injected fetch shim (#443, extends #331 dbTokenShim)', () => {
  it('attaches x-ainative-primitive-token on a /api/primitive/{name}/... call when that primitive has a token', async () => {
    const proxyToken = mintPrimitiveProxyToken('coffee-shop', 'zerocommerce', 1_700_000_000)
    const shim = dbTokenShim('', { zerocommerce: proxyToken })
    const { init } = await runShimAgainst(shim, '/api/primitive/zerocommerce/commerce/products')
    expect(init.headers.get('x-ainative-primitive-token')).toBe(proxyToken)
  })

  it('does NOT attach a primitive token when the request is for a DIFFERENT primitive than the one with a token', async () => {
    const proxyToken = mintPrimitiveProxyToken('coffee-shop', 'zerocommerce', 1_700_000_000)
    const shim = dbTokenShim('', { zerocommerce: proxyToken })
    const { init } = await runShimAgainst(shim, '/api/primitive/zeropipeline/pipelines')
    // No matching token → the shim leaves init untouched (undefined, since the
    // call was made with none) rather than fabricating headers.
    expect(init === undefined || !init.headers || !init.headers.has('x-ainative-primitive-token')).toBe(true)
  })

  it('still attaches the ZeroDB data token on /api/db calls, unaffected by the primitive-token addition', async () => {
    const shim = dbTokenShim('db-token-abc', { zerocommerce: 'proxy-token-xyz' })
    const { init } = await runShimAgainst(shim, '/api/db/orders')
    expect(init.headers.get('x-ainative-db-token')).toBe('db-token-abc')
    expect(init.headers.has('x-ainative-primitive-token')).toBe(false)
  })

  it('does not touch headers at all for an unrelated fetch (e.g. a third-party API the app calls directly)', async () => {
    const shim = dbTokenShim('db-token', { zerocommerce: 'proxy-token' })
    const { init } = await runShimAgainst(shim, 'https://example.com/anything')
    expect(init === undefined || !init.headers || !init.headers.has('x-ainative-primitive-token')).toBe(true)
  })

  it('is a no-op (empty string) when there is nothing to inject', () => {
    expect(dbTokenShim('', {})).toBe('')
  })
})
